#include <string>
using namespace std;

class Solution {
public:
    int minFlipsToReverse(string s) {
        int n = s.size();
        int flips = 0;
        for (int i = 0; i < n / 2; ++i) {
            if (s[i] != s[n - 1 - i]) flips++;
        }
        return flips;
    }
};

class Solution {
    public int minFlipsToReverse(String s) {
        int n = s.length();
        int flips = 0;
        for (int i = 0; i < n / 2; i++) {
            if (s.charAt(i) != s.charAt(n - 1 - i)) flips++;
        }
        return flips;
    }
}

var minFlipsToReverse = function(s) {
    const n = s.length;
    let flips = 0;
    for (let i = 0; i < Math.floor(n / 2); i++) {
        if (s[i] !== s[n - 1 - i]) flips++;
    }
    return flips;
};
